const text = $json.content || $json.text || $json.output;

const clean = $input.first().json.content.parts[0].text
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

const meal = JSON.parse(clean);

const now = new Date();

meal.meal_id =
  `MEAL-${Date.now()}-${Math.random().toString(36).substring(2, 8)}`;

meal.date = now.toLocaleDateString('en-CA', {
  timeZone: 'Asia/Kolkata'
});

meal.time = now.toLocaleTimeString('en-IN', {
  hour: '2-digit',
  minute: '2-digit',
  hour12: false,
  timeZone: 'Asia/Kolkata'
});

// Normalize foods
if (!Array.isArray(meal.foods)) {
  meal.foods = [];
}

meal.foods_text = meal.foods
  .map(food => {
    if (typeof food === 'string') return food;

    return `${food.name || 'Unknown'} (${food.portion || '1 serving'})`;
  })
  .join(', ');

meal.meal_type = meal.meal_type || 'Other';
meal.description = meal.description || null;
meal.confidence = meal.confidence || 'Low';

meal.source = 'Photo';
meal.created_at = now.toISOString();

return [{ json: meal }];

